37	/**
38	 * Mostly used as a facade for all Petclinic controllers
39	 * Also a placeholder for @Transactional and @Cacheable annotations
40	 *
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Service
45	public class ClinicServiceImpl implements ClinicService {
46	
47	    private final PetRepository petRepository;
48	    private final VetRepository vetRepository;
49	    private final OwnerRepository ownerRepository;
50	    private final VisitRepository visitRepository;
51	    private final SpecialtyRepository specialtyRepository;
52	    private final PetTypeRepository petTypeRepository;
53	    private final CustomerCodeGenerator customerCodeGenerator;
54	    private final NamesakeCounter namesakeCounter;
55	
56	    public ClinicServiceImpl(
57	        PetRepository petRepository,
58	        VetRepository vetRepository,
59	        OwnerRepository ownerRepository,
60	        VisitRepository visitRepository,
61	        SpecialtyRepository specialtyRepository,
62	        PetTypeRepository petTypeRepository,
63	        CustomerCodeGenerator customerCodeGenerator,
64	        NamesakeCounter namesakeCounter) {
65	        this.petRepository = petRepository;
66	        this.vetRepository = vetRepository;
67	        this.ownerRepository = ownerRepository;
68	        this.visitRepository = visitRepository;
69	        this.specialtyRepository = specialtyRepository;
70	        this.petTypeRepository = petTypeRepository;
71	        this.customerCodeGenerator = customerCodeGenerator;
72	        this.namesakeCounter = namesakeCounter;
73	    }
74	
75	    @Override
76	    @Transactional(readOnly = true)
77	    public Collection<Pet> findAllPets() throws DataAccessException {
78	        return petRepository.findAll();
79	    }
80	
81	    @Override
