98	
99	    @Override
100	    @Transactional(readOnly = true)
101	    public Collection<Visit> findAllVisits() throws DataAccessException {
102	        return visitRepository.findAll();
103	    }
104	
105	    @Override
106	    @Transactional
107	    public void deleteVisit(Visit visit) throws DataAccessException {
