115	    }
116	
117	    @Override
118	    @Transactional(readOnly = true)
119	    public Collection<Vet> findAllVets() throws DataAccessException {
120	        return vetRepository.findAll();
121	    }
122	
123	    @Override
124	    @Transactional
125	    public void saveVet(Vet vet) throws DataAccessException {
126	        vetRepository.save(vet);
