163	    @Transactional(readOnly = true)
164	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
165	        return petTypeRepository.findAll();
166	    }
167	
168	    @Override
169	    @Transactional
170	    public void savePetType(PetType petType) throws DataAccessException {
