226	        petRepository.save(pet);
227	    }
228	
229	    @Override
230	    @Transactional
231	    public void saveVisit(Visit visit) throws DataAccessException {
232	        visitRepository.save(visit);
233	
234	    }
235	
236	    @Override
237	    @Transactional(readOnly = true)
238	    public Collection<Vet> findVets() throws DataAccessException {
239	        return vetRepository.findAll();
240	    }
241	
242	    @Override
243	    @Transactional
244	    public void saveOwner(Owner owner) throws DataAccessException {
245	        if (owner.isNew()) {
246	            if (owner.getCustomerCode() == null) {
247	                owner.setCustomerCode(customerCodeGenerator.generate(owner));
248	            }
249	            owner.setNamesakeCount(namesakeCounter.count(owner));
250	        }
251	        ownerRepository.save(owner);
252	
253	    }
254	
255	    @Override
256	    @Transactional(readOnly = true)
257	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
258	        return ownerRepository.findByLastName(lastName);
259	    }
260	
261	    @Override
262	    @Transactional(readOnly = true)
263	    public Collection<Owner> findOwnerByTelephone(String telephone) throws DataAccessException {
264	        return ownerRepository.findByTelephone(telephone);
265	    }
266	
267	    @Override
268	    @Transactional(readOnly = true)
269	    public long countOwnersByCity(String city) throws DataAccessException {
270	        return ownerRepository.countByCity(city);
271	    }
272	
273	    @Override
274	    @Transactional(readOnly = true)
275	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
276	        return ownerRepository.countByRegistrationDate(registrationDate);
277	    }
278	
279	    @Override
280	    @Transactional(readOnly = true)
281	    public Collection<Owner> findOwnersInHousehold(String lastName, String address) throws DataAccessException {
282	        String targetLastName = TextNormalizer.normalizeForComparison(lastName);
283	        String targetAddress = TextNormalizer.normalizeForComparison(address);
284	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
285	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getLastName()).equals(targetLastName))
286	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getAddress()).equals(targetAddress))
287	            .collect(Collectors.toList());
288	    }
289	
290	    @Override
291	    @Transactional
292	    public String joinHousehold(Owner owner, Collection<Owner> existingMembers) throws DataAccessException {
293	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
294	        owner.setHouseholdId(householdId);
295	        for (Owner member : existingMembers) {
296	            if (!householdId.equals(member.getHouseholdId())) {
297	                member.setHouseholdId(householdId);
298	                ownerRepository.save(member);
299	            }
300	        }
301	        return householdId;
302	    }
303	
304	    @Override
305	    @Transactional(readOnly = true)
306	    public Collection<Visit> findVisitsByPetId(int petId) {
307	        return visitRepository.findByPetId(petId);
308	    }
309	
310	    @Override
311	    @Transactional(readOnly = true)
312	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
313	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
314	    }
315	
316	    private <T> T findEntityById(Supplier<T> supplier) {
317	        try {
318	            return supplier.get();
319	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
320	            // Just ignore not found exceptions for Jdbc/Jpa realization
321	            return null;
322	        }
323	    }
324	
325	}
